import { readFileSync, writeFileSync } from 'node:fs';
import { createScenario, stepScenario, captureScenario, restoreScenario } from '../../src/core/scenarios';
import { createHash } from 'node:crypto';
import { subscribeSimulation } from '../../src/core/history-hooks';
import { SCENARIOS } from '../../src/scenarios/campaigns';
import { steerEscort, steerDefense, routeCommands } from '../../scripts/scenarios/route-strategy';
const results = [];
const strategySource = readFileSync('scripts/scenarios/route-strategy.ts', 'utf8');
const strategySha256 = createHash('sha256').update(strategySource).digest('hex');
const restoreDuringPlay = process.argv[3] === 'restore';
for (const definition of Object.values(SCENARIOS).filter(d => d.escort || d.events.some(e => e.id === 'wave-1'))) {
  let s = createScenario(definition); const commands: unknown[] = []; let continued = false; const routeIntents: unknown[] = [];
  let unsubscribe = subscribeSimulation(s.state, {command:(side, command)=>commands.push({tick:s.state.tick,time:s.state.time,side,command})}); const deaths: number[] = []; let attacks = 0; const checkpointTimes: number[] = []; let lastCheckpoint = 0;
  while (s.runtime.outcome === 'playing' && s.state.time <= definition.rules.timeLimit) {
    if (definition.escort) steerEscort(s); else steerDefense(s);
    stepScenario(s);
    for (const event of s.state.events) { if (event.type === 'attack') attacks++; if (event.type === 'death' && event.source !== undefined) deaths.push(event.source); }
    if (restoreDuringPlay && !continued && s.runtime.outcome === 'playing' && s.state.time >= (definition.escort ? 12 : 40)) {
      routeIntents.push(...routeCommands(s)); unsubscribe(); s = restoreScenario(captureScenario(s)); continued = true;
      unsubscribe = subscribeSimulation(s.state, {command:(side, command)=>commands.push({tick:s.state.tick,time:s.state.time,side,command})});
    }
    if (s.runtime.escort.checkpoint > lastCheckpoint) { checkpointTimes.push(s.state.time); lastCheckpoint=s.runtime.escort.checkpoint; }
  }
  unsubscribe();
  const waves = definition.events.filter(e=> /^(wave|ambush)-/.test(e.id)).map(e=>({ id:e.id, fired:s.runtime.triggers[e.id]?.count??0, actors:e.actions.flatMap(a=>a.type==='spawn'?a.actors:[]).map(a=>({label:a.label,id:s.runtime.labels[a.label],dead:deaths.includes(s.runtime.labels[a.label]),remaining:s.state.entities.find(e=>e.id===s.runtime.labels[a.label])?.hp??0})) }));
  const restored = restoreScenario(captureScenario(s));
  const r = {commands,routeIntents:[...routeIntents,...routeCommands(s)],continued,id:definition.id,outcome:s.runtime.outcome,reason:s.runtime.reason,time:s.state.time,attacks,completed:s.runtime.completed,checkpointTimes,waves,actions:s.runtime.commandCounts,reinforcementRemaining:s.runtime.reinforcementRemaining,roundtrip:restored.runtime.outcome===s.runtime.outcome&&restored.state.time===s.state.time,own:s.state.entities.filter(e=>e.side===0&&e.hp>0&&!e.illusion).map(e=>({id:e.id,role:e.role,hp:e.hp,x:e.x,y:e.y}))};
  results.push(r); console.log(definition.id,r.outcome,r.time.toFixed(2),r.waves.map(w=>`${w.id}:${w.actors.filter(a=>a.dead).length}/${w.actors.length}`).join(' '));
}
writeFileSync(process.argv[2] ?? 'work/route-strategy/attempt-3.json',JSON.stringify({schemaVersion:1,base:'fc62412',strategy:'scripts/scenarios/route-strategy.ts',strategySha256,strategySource,restoreDuringPlay,results},null,2));
if (results.some(r=>r.outcome!=='won'||r.waves.some(w=>w.fired!==1||w.actors.some(a=>!a.dead)))) process.exitCode=1;
